@pytest.mark.parametrize('drift', [None, 'agent', 'grant', 'revision']) def test_drain_keeps_approval_and_terminal_publication_until_work_completes(connected_local, drift): setup, binding, native = connected_local deps, app, client, headers, *_ = setup deps.config.feature_hitl = True opened = admit(setup, binding, 'drain-approval-open', 'runtime.start', new_session=True) wait_receipt(setup, opened) session = opened['scope']['session_id'] turn = admit(setup, binding, 'drain-approval-turn', 'turn.submit', session_id=session, text='Synthetic task') wait_receipt(setup, turn) replies = [] async def reply(request, decision, response): replies.append(decision) native.native.reply_native_approval = reply with deps.connection_factory.unit_of_work(write=False) as uow: stream = dict(uow.connection.execute('SELECT * FROM execution_local_streams').fetchone()) request = dict(schema_version=1, request_id=7, request_hash='a' * 64, method='item/commandExecution/requestApproval', params={'threadId': 'native-thread', 'turnId': 'turn-from-native', 'itemId': 'item'}) client.portal.call(native.native.queue.put, RuntimeEvent(stream['server_id'], stream['executor_id'], session, stream['stream_epoch'], 0, 'approval_request', request['method'], {'native_approval': request, 'native_approval_display': dict(request)}, turn['operation_id'])) approvals = [] def captured(): rows = client.get('/api/v1/approvals', headers=headers['operator'], params={'workspace': binding['workspace_id'], 'status': 'pending'}).json()['data']['items'] approvals[:] = [row for row in rows if row['action'] == 'execution.native.respond'] return len(approvals) == 1 eventually(captured) response = client.post('/v1/runtime/shutdown', headers=headers['operator'], json={'timeout_seconds': .02}) assert response.status_code == 202 and response.json()['phase'] == 'waiting' assert not native.native.stopped and len(native.native.sent) == 1 owner = app.state.embedded_dispatch_owner assert not owner._stopping.is_set() and not owner.pump._stopping.is_set() assert client.get('/healthz').status_code == 200 for action in ('turn.submit', 'turn.steer'): refused = client.post('/v1/runtime/intents:resolve', headers=headers['subject'], json={ 'client_intent_id': 'drain-refuse-' + action, 'intent': action, 'binding_id': binding['binding_id'], 'workspace_binding_id': binding['workspace_binding_id'], 'session_id': session, 'text': 'Must not be admitted'}) > assert refused.status_code == 200, refused.text E AssertionError: {"error":{"code":"VALIDATION_ERROR","stage":"intent.resolve","message":"The selected adapter does not support this control target.","possible_effect":false,"retry_safe":false,"operation_id":null,"action":""}} E assert 422 == 200 E + where 422 = <Response [422 Unprocessable Entity]>.status_code
